import{_ as a}from"./chunks/46f538bbf8b9a8749813.Cqo2pSeL.js";import{_ as l,C as r,o as t,c as o,j as e,a as n,E as s,a5 as u}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"别太在意（这正在毁掉你的人生）","description":"","frontmatter":{"title":"别太在意（这正在毁掉你的人生）","originalTitle":"Stop Caring So Much (It’s Ruining Your Life)","date":"2024-05-04","originalUrl":"https://thedankoe.com/letters/stop-caring-so-much-its-ruining-your-life/","minutes":14,"sourceHash":"aab335657bbc49cbed57e578b8e31ed7e6c428ae7b8be13922bda2fd5af6f636","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/stop-caring-so-much-its-ruining-your-life/"}]]},"headers":[],"relativePath":"letters/stop-caring-so-much-its-ruining-your-life.md","filePath":"letters/stop-caring-so-much-its-ruining-your-life.md"}'),h={name:"letters/stop-caring-so-much-its-ruining-your-life.md"};function c(d,p,m,f,g,_){const i=r("ArticleMeta");return t(),o("div",null,[p[0]||(p[0]=e("h1",{id:"别太在意-这正在毁掉你的人生",tabindex:"-1"},[n("别太在意（这正在毁掉你的人生） "),e("a",{class:"header-anchor",href:"#别太在意-这正在毁掉你的人生","aria-label":'Permalink to "别太在意（这正在毁掉你的人生）"'},"​")],-1)),s(i),p[1]||(p[1]=u('<p><a href="https://www.youtube.com/embed/ReyMCKC-FwU?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>环顾四周。</p><p>每个人都压力大到快疯了。</p><p>我们都想成就大业，但要专注在这些大事上正变得极其困难……所以它们永远也完不成。</p><p>我们的头脑中充斥着：</p><ul><li>追求你自己的目标，而不是你父母（或朋友、伴侣、老板）期望的目标所带来的<em>风险</em>。</li><li>被那些与你目标不一致的人告知你应该在意什么——学什么技能，支持哪个国家，忌口哪些食物。</li><li>想到你必须去上的班、你要浪费多少时间，以及所有你将无法去做的事情。</li><li>如果你决定走自己的路并掌控自己的人生，别人会怎么看。他们到底会怎么看？</li></ul><p>这些想法可不怎么好应付。</p><p>如果你的朋友或父母不支持你——甚至试图阻止你——这会变得极其痛苦。你可能会失去生活中的某些人。你可能会失去一部分自我认同。这很伤人。</p><p>问题在于他们并不了解你所知道的。</p><p>他们没有接触过同样的信息、教育和潜力，所以他们看不到机会。</p><p>他们的头脑仍然被服务于他们过时目标的信念所编程。他们很难相信你的新尝试会成功，因为他们所知道的“可能”仅限于他们自己做过的事。</p><p>父母们最擅长这个了。</p><p>他们一出生就被分配了目标。他们追求这些目标并看到了结果。他们的身份认同被塑造了，他们的头脑也是如此。</p><p>如果他们在成年后不继续拓宽自己的认知，他们的思想就会僵化。与他们认知不符的事物在他们看来毫无意义，而人们总是讨厌他们不理解的东西。</p><p>这是你必须意识到的第一点：</p><p>没人会准许你去做你想做的事。</p><p>他们没有接触过你接触的信息。</p><p>他们没有你讲给自己的那个故事。</p><p>除非他们足够成熟，能对那个故事敞开心扉，否则在某个时刻，你必须跳出舒适的巢穴，并相信你能学会飞翔。</p><p>更进一步说，你每天能投入到自己目标上的专注力是有限的。</p><p>难怪人们生活在持续的压力之中。</p><p>我们无法专注。</p><p>我们太过关注别人的目标，以至于对自己的目标毫无注意力可言。</p><p>我们一醒来就抓起手机，让新闻、建议、末日预言以及混得比我们好的人塞满大脑。找到慰藉的唯一方法就是继续滑动屏幕，让自己感觉像是在取得进展。</p><p>大脑渴望秩序。这就是为什么你感觉糟透了。</p><p>你的注意力并没有集中在对未来的某个单一愿景上——一个强大到让任何干扰都无法穿透的愿景。</p><p>你只有一个选择。</p><p>去深切感受你的处境。</p><p>意识到如果你继续沿着这条路走下去，你的人生最终会走向何方。</p><p>对自己毫无进展的状态感到彻底厌倦。</p><p>利用那种负面能量，精准聚焦于你一直拖延的那个有意义的目标……你知道的，就是那个一直在你耳边唠叨的内心声音。</p><ul><li>“你生来注定不止于此。”</li><li>“你具备成功的潜质。”</li><li>“你不必和别人落得一样的下场。”</li></ul><p>认真的，去<em>感受</em>你的处境。别再逃避了。你必须增加你想要实现的目标的分量。</p><p>没有实现目标的痛苦必须超过过着安逸生活的痛苦。</p><p>你必须消除那些干扰，正是它们让你对“成为命中注定之人所带来的痛苦”感到麻木。</p><h2 id="自律源于清晰-而非强迫" tabindex="-1">自律源于清晰，而非强迫 <a class="header-anchor" href="#自律源于清晰-而非强迫" aria-label="Permalink to &quot;自律源于清晰，而非强迫&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>大多数人不理解自律。</p><p>它本来不应该是一件困难的事。</p><p>它是你清楚自己想要什么并且绝不退而求其次的副产品。它是一个有序头脑的副产品。也就是说，保持对未来清晰的愿景，并通过学习和行动来填补不够清晰的认知空白。</p><p>人们在自律上苦苦挣扎的原因，是因为他们被无关紧要的事分散了注意力。</p><ul><li>他们忘记了自己想成为谁。</li><li>他们忘记了自己有何能力。</li><li>他们忘记了自己想要产生的影响。</li></ul><p>你不够自律，因为你还不是那个能够顺理成章实现自己既定目标的人。</p><p>一个真正认同自己是健美运动员的人，在健康饮食和去健身房这件事上不会觉得困难。他们就是会去做。</p><p>一个真正认同自己是作家的人，在腾出时间构思创意、长途散步和写作这件事上不会觉得困难。</p><p>一个真正认同自己是玩家的人，在网上喷人、拥有末日思维、每天在屏幕前毁掉自己健康8到10个小时这件事上不会觉得困难。</p><p>健美运动员会把这种生活方式视为人间地狱。要想让他们采纳玩家的生活方式而不发疯并痛恨自己的人生，几乎是不可能的。他们会极其残酷地意识到自己未能实现的目标。</p><p>每种身份认同都有其取舍。它们都需要做出牺牲，从而让他们能够实现自己选择的目标。</p><p>这引出了我们变得自律的第一步：</p><p><strong>1) 消除干扰</strong></p><p>问问自己：</p><p>你知道自己为什么在做你现在正在做的事吗？</p><p>过去一个月里你问过自己这个问题吗？</p><p>你为什么去上学？做那份工作？创立那家公司？做那个锻炼？</p><p>这是你的选择吗？还是你的父母、朋友或文化强行植入你脑海的目标？</p><p>审查你的生活，找出那些你甚至不知道自己正在追求的目标。</p><p>拿个笔记本坐下来，写下你正在做的每一件事以及你做它的原因。</p><p>如果你没有一个好的答案，那就是一个干扰。你正在把情感能量浪费在别人的梦想上，所以你没有足够的精力去追求自己的梦想。</p><p>如果你需要理清思路的帮助，并且是纸笔的粉丝，去买一本我的 <a href="https://thedankoe.store/products/the-foci-planner" target="_blank" rel="noreferrer">FOCI Planner</a>。</p><p><strong>2) 把生活当成一场游戏</strong></p><p>我一直对“反目标”（anti-goals）这个简单的概念很着迷。</p><p>反目标<em>不是</em>你<em>不想</em>实现的目标。</p><p>它们是为了实现某个目标你不愿意做出的牺牲。</p><p>举个例子，如果我想建立一家市值十亿美元的公司，为了达到这个目标，我<em>不</em>愿意牺牲什么？</p><p>大多数拥有这种宏大目标的人很少关注他们在这一路上失去的东西：他们的健康、他们的家庭以及他们的理智。</p><p>另一方面，我知道在建立那家十亿美元公司的同时，保持健康、拥有良好的人际关系并维持心理健康是可能的。</p><p>是的，这会花费更多的时间和精力，但除了这么做还能怎样呢？难道就因为你没有节制力或自律去承担不止一种责任，就任由你的人生在眼前燃烧殆尽吗？</p><p>这就是反目标的绝妙之处。它们把生活变成了一场有趣的游戏。</p><p>它们满足了触发心流的许多条件——而心流正是让我们对电子游戏上瘾的主要特征。</p><ul><li><strong>挑战</strong> —— 一个触手可及并考验你技能的目标。</li><li><strong>技能</strong> —— 如果你的技能远低于挑战，你会焦虑。如果远高于挑战，你会无聊，这表明你需要选择一个更大或更小的挑战，而不是放弃。</li><li><strong>清晰度</strong> —— 目标从大到小的层级结构，让你更容易开始朝着对未来的愿景迈进。</li><li><strong>反馈</strong> —— 你确切地知道自己何时在取得进展，这感觉很好。你不会觉得陷入了毫无结果的重复任务循环中。</li><li><strong>规则</strong> —— 规则或边界构建了你感知世界的方式。你的大脑有了更多空间去留意有助于实现你目标的信息。</li></ul><p>当你把生活变成一场游戏时，你就会对“取得进展”这件事上瘾。</p><p><strong>3) 重塑自己</strong></p><p>所有的改变都是行为的改变。</p><p>所有行为的改变都是身份认同的改变。</p><p>所以，所有的改变都是身份认同的改变。</p><p>你就是你反复做的事。</p><p>此时此刻，你对那些在你脑海中挥之不去的目标是保持自律的。</p><p>躺在床上，整天看Netflix和打游戏，你不会觉得这有多难。</p><p>对于许多高绩效者来说，那是世界上最难的事。他们无法想象自己那样做。朝着那些成就他们的目标毫无进展，这种痛苦会把他们活活生吞了。</p><p>如此说来，你的旅程将会是痛苦的。</p><p>你正在让旧的自我消亡。</p><p>你不会想要抛弃那些阻碍你的信念和习惯。</p><p>那是第一步。意识到困难是一个好兆头。一个继续前进的兆头。</p><p>第二步是重新编程你的大脑，使其朝着创造新身份认同的新目标运作。</p><ul><li>把自己扔进一个与你想成为的人相契合的新环境中。</li><li>让你的大脑沉浸在观念、信息和知识中，这些会让你接触到新的目标以及实现这些目标的方法。</li><li>通过你理想生活方式的视角来看待每一种情况，并据此做出决定。</li></ul><p>把自己扔进深水区，然后逼自己学会游泳。</p><p>大多数人出于恐惧不愿迈出那一步。</p><p>这就是为什么我们需要谈谈自信。</p><h2 id="一条通往自信的非常规之路" tabindex="-1">一条通往自信的非常规之路 <a class="header-anchor" href="#一条通往自信的非常规之路" aria-label="Permalink to &quot;一条通往自信的非常规之路&quot;">​</a></h2><p>当我开始写作时，我的人生改变了。</p><p>不只是写私密日记——这确实极其有用——而是为了我未来的某个大目标进行公开写作。</p><p>写作通过以下方式帮我对自己的想法和人生方向建立起自信：</p><ul><li>暴露在公众的批评之下，迫使我审视自己的信念。</li><li>找到拥有共同目标的朋友和人脉，让我不再感觉自己是个异类。</li><li>练习一项技能，并每天都能看到自己在进步。</li><li>经常失败让我保持谦逊，并给了我那些我通常找不到的新方向。</li></ul><p>写作并非培养自信的唯一途径，但人们对写作的理解完全错了。</p><p>他们认为这只是一种技能或爱好。</p><p>他们没有把它看作是让我们成为人类的东西。</p><p>我们是唯一能通过文字记录知识来<em>传承</em>信息的物种，以此帮助后人避开危险并不断进化。无论是作为个体还是作为集体，写作都是我们能走到今天的原因。</p><p>写作始于洞穴里的雕刻，现在已变成了互联网上的思想。</p><p>洞穴里的雕刻几乎无人问津，但有了互联网，你便拥有了改变自己以及成千上万人生活的能力。</p><p>写作是目标与利润的交汇点。不要低估那种力量。</p><h3 id="_1-解构你的目标" tabindex="-1">1) 解构你的目标 <a class="header-anchor" href="#_1-解构你的目标" aria-label="Permalink to &quot;1) 解构你的目标&quot;">​</a></h3><p>你不自信，是因为你还没有在你的“失败履历”上投资。</p><p>你花了太多时间驻留在别人人生道路的舒适区里。</p><p>你没能跳出大众的框架，没能独立思考，没能设定自己的目标，也没能不管花多长时间都去实现它们。</p><p>你不自信，是因为除了那些前人已经做过的事情之外，你在任何事情上都没有拿到结果。</p><p>坐下来理理你的思绪。</p><p>你到底想从生活中得到什么？</p><p>是和别人一样无聊的道路吗？</p><p>不是？</p><p>那么唯一的选择就是：</p><ul><li>通过观察大多数人的行为以及这些行为导致的后果，明确你在生活中不想要什么。</li><li>如果你想在生活中取得更多成就，那就做和所有人相反的事。</li><li>思考你的未来，并将其拆解为你必须实现的目标和你必须采取的行动。</li><li>每天利用能帮助你实现这些目标的材料来进行自我教育。</li><li>留出专门的时间进行专注工作，以构建你对未来的愿景。</li></ul><p>然后，开始行动。</p><p>自信来源于一遍又一遍地去做你认为不舒服的事，并最终意识到它其实并没有那么糟。</p><h3 id="_2-创办一家企业" tabindex="-1">2) 创办一家企业 <a class="header-anchor" href="#_2-创办一家企业" aria-label="Permalink to &quot;2) 创办一家企业&quot;">​</a></h3><p>如果你认真思考过你在生活中真正想要什么，那么创办一家企业就不是一个可有可无的选项。</p><p>你渴望自主权，渴望做自己享受的工作，渴望对世界产生影响，从而满足你作为人类想要为全人类做出有价值贡献的需求。</p><p>企业并不是为了拥有私人飞机和豪宅的某种资本主义追求。</p><p>企业是你解决问题的方式。</p><p>企业是你构建属于自己东西的方式。</p><p>企业是你通过价值交换为全人类做出贡献的方式。</p><p>企业是你夺回生活掌控权的方式。</p><p>企业是你对自己的兴趣和专长建立自信的方式。</p><p>大多数人被程序化地设定为对“企业”或“商业”一词产生负面反应。</p><p>“这太难了。”</p><p>“金钱是邪恶的。”</p><p>“这是一种肤浅的追求。”</p><p>然后，他们继续做着最困难的事：</p><p>他们通过妖魔化任何可能危及舒适区的人和事，来逃避自己发挥潜能、自我实现和自我超越的渴望，而他们甚至没意识到自己已对这种舒适上瘾了。</p><p>他们继续作为螺丝钉，在一家靠卖产品赚取数百万利润的商业机器中运转。他们哭诉大多数企业是多么不道德，却为其中一家工作，而且没有意识到对抗它的唯一方法就是自己创办一家合乎道德的企业。</p><p>他们说这很肤浅，但只要一有时间他们就会去分散自己的注意力。他们永远无法逃离表层。他们从不将商业视为一种载体，借此潜入生活在未知道路上所能提供的深处。</p><p>企业是你个人价值的店面。</p><p>它是你自己、你的目标和你的价值观的公开展示。</p><p>企业是你自身的延伸。</p><h3 id="_3-公开写作" tabindex="-1">3) 公开写作 <a class="header-anchor" href="#_3-公开写作" aria-label="Permalink to &quot;3) 公开写作&quot;">​</a></h3><p>写作是一种超能力。</p><ul><li>你能更快地实现目标。</li><li>你能吸引志同道合的人。</li><li>你可以从零经验开始。</li><li>你会对别人看到你的想法感到自在。</li></ul><p>并且，写作是媒体的基础。</p><p>你在网上看到的一切，从帖子到视频再到广告，都是从写作开始的。</p><p>媒体就是注意力所在的地方。</p><p>如果你想在生活中做任何有价值的事，你都需要有自己的注意力来源。</p><p>你不能再指望你的老板去吸引注意力、招揽客户，然后分配给你一些微不足道的工作，只为了换取固定的一点钱去向那些客户提供产品或服务。</p><p>你必须亲自做以上所有的事。</p><p>对于没有资金或经验的新手来说，公开写作是第一步。</p><p>写作是一种零门槛的商业模式，它允许你为你感兴趣的任何事物建立受众群体。</p><ul><li>选择 2-3 个你想写的主题，这些主题应当是你想要去学习、想要在其中打响名声，并想要将其转化为一份有意义事业的领域。</li><li>通过观察来学习。观察这些领域里的其他人都在写些什么，他们是如何写的，以及他们为什么要那样表达。</li></ul><p>如果你在想：“这个我也能写”，那就去写……在互联网上，你不需要得到任何人的允许。</p><p>如果你不知道从何开始，可以考虑报名参加 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>。</p><h3 id="_4-结交新朋友" tabindex="-1">4) 结交新朋友 <a class="header-anchor" href="#_4-结交新朋友" aria-label="Permalink to &quot;4) 结交新朋友&quot;">​</a></h3><p>智囊团 (Mastermind)：</p><p>多个头脑为了实现一个共同目标而协同工作。</p><p>在过去，你需要为了人脉而努力奔波，才能让你的企业取得成功。</p><p>现在，你只需点击一个按钮就可以联系到任何人。</p><p>你的成功不再由你的社会经济地位和所处地理位置决定。</p><p>它取决于你与谁建立了联系，以及他们能够传递给你的机会。</p><p>你该如何寻找这些人脉？</p><p>首先要有一个你想实现的目标。</p><p>你该如何吸引别人关注那个目标？</p><p>创办一家以实现该目标为使命的企业。</p><p>你该如何走到那些拥有广阔人脉的人面前？</p><p>公开写作以传播你的想法。</p><p>这和自信又有什么关系呢？</p><p>好吧，其实很明显。</p><p>如果你不去突破自己的极限并经历失败，你是无法培养出自信的。</p><p>目标、企业和写作——按照这个顺序——就是你无限次重复这个过程的方式。除了你自己设定的限制之外，没有任何限制。</p><p>你在职场中迟早会遇到天花板。有那么一个人在掌控着你所能达到的上限。</p><p>如果你不赶上由技术、人工智能和互联网驱动的进化列车，不在虚拟现实（互联网和社交媒体）中“开店”，它们就会把你淘汰。</p><p>通过在网上现身并与人们交谈，你结交了朋友。</p><p>就像你在派对上那样。</p><p>在互联网上，你可以用你的品牌和思想来提升你的社会认同。</p><p>在互联网之外，你可以用汽车、外貌和物质财富来提升你的地位。</p><p>很显然，哪一种方式能导向更好的生活。</p><p>在坚持写作 4 年之后，只要我有他们想要的东西，我几乎可以给任何人发消息并与他们合作。</p><p>举个例子，戈登·拉姆齐（Gordon Ramsey）在关注我。</p><p>我不知道我有什么需要向他求助的，但谁知道呢，说不定以后会有什么交集。</p><h3 id="_4-发布你的作品" tabindex="-1">4) 发布你的作品 <a class="header-anchor" href="#_4-发布你的作品" aria-label="Permalink to &quot;4) 发布你的作品&quot;">​</a></h3><p>要理解自信，我们必须理解故事。</p><p>故事 = 蜕变。</p><p>你不自信，是因为你被困在别人的故事里。你没有机会蜕变成你注定要成为的那个人。</p><p>你无法完全掌控自己摆脱故事低谷、走向高潮并迎来大团圆结局的能力。</p><p>走出低谷的道路就是不断试错，这也是生活本身的本质。</p><p>你的第一次写作尝试会很烂。</p><p>你的第一次产品发布会很烂。</p><p>你的第一次结交朋友尝试也会很烂。</p><p>99% 的人极度不自信的原因是，他们下意识地认为，无需做任何能够孕育更稳定自信基础的事情，自信就会自然产生。</p><p>自信就是不断地改进。</p><p>发布你的文章，然后被人骂作白痴。</p><p>发布你的产品，然后收集负面反馈。</p><p>展现你自己，让人们暴露你的缺点。</p><p>只有这样，一旦你意识到了问题所在，你才能知道该去改进什么。</p><p>你无法改进没有发布的东西。</p><p>如果你没有意识到问题，你就无法改进。</p><p>死在你的舒适区黑洞里会让你在这两件事上都毫无作为。</p><p>你决定在那里停留的时间越长，培养自信所需的时间也就越长。</p><p>你可以读完这篇文章后对自己的生活无所作为，因为你“还没了解够多，无法开始”。</p><p>或者，你终于可以迈出那一步，把你的生命投入到学习和建设中去，而不是指望一切都靠别人施舍。</p><p>今天就到这里。</p><p>祝你本周剩下的日子过得愉快。</p><p>– Dan</p><hr><p><a href="/en/letters/stop-caring-so-much-its-ruining-your-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',200))])}const x=l(h,[["render",c]]);export{q as __pageData,x as default};
